/*
 * ============================================================
 *  NixieClockCardWebgl — Home Assistant Custom Card  v1.0.0
 *  Usage: add to resources as /local/nixie-clock-card-webgl.js
 * ============================================================
 *
 *  Variante WebGL de nixie-clock-card, dessinee d'apres la vraie horloge
 *  nixie de Chris (6 tubes IN-14 separes, chiffres orange, LED cyan au pied
 *  de chaque tube, barrettes a 2 points LED, socle acrylique noir).
 *
 *  Minimal config:
 *
 *    type: custom:nixie-clock-card-webgl
 *
 *  All options:
 *
 *    use_military: true          # 24h (default: true)
 *    hide_seconds: false         # 4 tubes au lieu de 6 (default: false)
 *    under_color: "var(--accent-color)"   # LED des pieds + separateurs (default: accent du theme)
 *
 *    # -- rendu (valeurs reglees a l'oeil au banc d'essai le 25/09/2026) --
 *    glow:     1.20   # intensite du halo orange
 *    glow_r:   10.0   # rayon du halo, px
 *    core:     0.35   # coeur du trait qui tire vers le jaune-blanc
 *    flicker:  0.06   # amplitude du scintillement du gaz (0 = fixe, moins de calcul)
 *    ghost:    0.12   # visibilite des chiffres eteints et de la maille
 *    fade:     180    # duree du fondu entre deux chiffres, ms
 *    under:    1.00   # intensite de la LED au pied des tubes
 *    under_h:  0.45   # jusqu'ou le cyan monte dans le tube
 *    glass:    0.35   # reflets sur les bords du tube
 *    sep:      1.00   # intensite des LED des separateurs
 *
 *    # -- GLITCH le chat (identique a nixie-clock-card) --
 *    glitch: true  glitch_size: 64  glitch_right: -26  glitch_top: -40
 *    glitch_color: (default: under_color)  glitch_opacity: 0.8
 *    glitch_dur: 2400  glitch_gap: 25
 *
 *  Pas d'editeur (choix delibere) : tout se regle en YAML.
 * ============================================================
 */

