(function(){
'use strict';

const NCW_VERSION = '1.0.0';
const NCW_TAG = 'nixie-clock-card-webgl';

const NCW_IS_IPAD = /iPad/.test(navigator.userAgent) ||
  (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
const NCW_IS_LOW_POWER = NCW_IS_IPAD || /iPhone|iPad|iPod|Android|Mobile|HomeAssistant/i.test(navigator.userAgent);

// Espace logique du dessin (px CSS au banc) : le shader travaille dans ce repere,
// le canvas reel n'en est qu'une mise a l'echelle.
const NCW_W = 355, NCW_H = 110;

// Valeurs reglees a l'oeil au banc d'essai (ha-card-preview-bench, 25/09/2026) :
// ne pas les rechoisir au juge.
const NCW_DEF = { glow:1.20, glow_r:10.0, core:0.35, flicker:0.06, ghost:0.12,
                  fade:180, under:1.00, under_h:0.45, glass:0.35, sep:1.00 };

/* Planche Hybl 744x200 : 12 cellules 62x100 (0-9, espace, tiret), rangee du haut. */
const NCW_SHEET = '';

/* GLITCH le chat — path detache (viewBox 15 28 666 666 + transforms inline). */
const NCW_GLITCH_PATH = "m0 0v-158.6s0.791-10.141 7.723-10.628c6.933-0.488 8.139 9.543 11.241 9.776s11.982 6.911 13.099 13.453c1.118 6.541-3.822 37.415-1.97 57.793 1.853 20.377 15.221 52.354 15.221 52.354s27.951-18.589 39.401-25.283c11.451-6.694 33.339-16.533 31.966-22.111-1.373-5.577 3.567-21.633 7.272-25.338 3.705-3.704 6.304-11.528 11.488-14.1s12.594-1.336 15.682-3.189c3.087-1.852 4.94-3.088 8.027-2.471 3.088 0.619 12.789 17.982 17.201 18.254s18.85 18.528 23.672 18.044c4.822-0.482 16.554-4.187 27.052-2.953 10.498 1.235 16.29 6.524 16.173 9.438-0.118 2.913-15.438 14.215-15.438 14.215s10.38 5.988 8.527 9.693c-1.852 3.704-24.179 20.346-33.393 24.993-9.214 4.646-23.916 9.143-23.916 9.143l-6.11 6.392s-30.44 24.309-33.528 31.101c-3.087 6.793-6.466 43.228-8.79 49.092-2.325 5.866-28.877 31.8-31.347 37.358-2.47 5.557-20.267 69.25-82.127 91.39-58.662 20.994-120.41 4.939-146.35 6.174-25.935 1.235-58.707 16.767-70.417 22.895s-77.165 67.877-98.16 96.282c-22.159 29.981-27.787 65.455-3.102 81.045 29.071 18.359 23.015 21.522 20.16 26.432-2.855 4.908-13.305 6.925-24.135 3.137-10.83-3.787-34.913-13.667-42.94-39.601-6.997-22.607 0-80.276 60.515-140.79 65.236-65.237 105.59-82.744 106.21-88.302 0.618-5.558-2.47-11.732-2.47-11.732l-0.5-4.766-1.848-6.842 2.348-6.3s-0.617-10.498 2.47-17.908c3.088-7.409 11.968-21.881 11.233-26.378-0.735-4.496-8.763-22.404-6.293-26.726 2.47-4.323 28.405-22.23 31.493-27.787 3.087-5.558 8.645-15.438 12.349-17.908 3.705-2.47 8.538-4.803 9.209-5.566 0.672-0.764 1.098-3.171 1.098-3.171h57.672v5.962s-1.597 2.621-1.752 3.701c-0.154 1.081 0.309 6.175-5.094 8.8-5.403 2.624-24.773 5.597-25.817 6.503s-2.125 1.524-3.669 2.296-6.792 8.491-9.725 10.806c-2.933 2.316-9.454 8.494-9.454 8.494l1.633 1.574s19.862-2.967 43.944-3.43c24.083-0.463 32.654 4.208 36.242 4.034 3.587-0.175 8.527-3.261 10.071-5.578 1.543-2.315 2.933-7.873 4.168-8.953 1.235-1.081 10.96-21.304 12.195-24.083 1.247-2.758 4.026-7.081 6.187-8.316 2.162-1.235 5.413-1.79 5.413-1.79";

/* ─────────────────────────── shaders ─────────────────────────── */
const VS = 'attribute vec2 p; varying vec2 v; void main(){ v = p*.5+.5; gl_Position = vec4(p,0.,1.); }';

// Echantillonnage d'une cellule, commun a toutes les passes.
// Point noir : le fond de la photo est un brun (29,10,9) opaque, sinon un rectangle
// teinte apparait dans chaque tube. Bord de cellule adouci pour la meme raison.
const GLSL_CELL = `
  vec3 cell(sampler2D t, float c, vec2 uv){
    uv = clamp(uv, vec2(0.004), vec2(0.996));
    vec3 s = texture2D(t, vec2((c + uv.x) / 12.0, uv.y * 0.5)).rgb;
    vec2 e = smoothstep(0.0, 0.06, uv) * smoothstep(0.0, 0.06, 1.0 - uv);
    return max(s - vec3(0.14, 0.06, 0.06), 0.0) * 1.2 * e.x * e.y;
  }`;

// Halo pre-floute CELLULE PAR CELLULE (sinon le halo d'un 3 ramasse le 2 et le 4
// voisins sur la planche). Separable, 2 passes, refait seulement si glow_r change.
const FS_BLUR = `precision highp float;
  varying vec2 v; uniform sampler2D uTex; uniform vec2 uDir; uniform float uR; uniform vec2 uSize;
  void main(){
    vec2 px = v * uSize;
    float cx0 = floor(px.x / 62.0) * 62.0;
    float cy0 = px.y < 100.0 ? 0.0 : 100.0;
    vec3 acc = vec3(0.); float wsum = 0.;
    for (int k = -12; k <= 12; k++){
      float t = float(k) / 12.0;
      float w = exp(-t*t*2.5);
      vec2 q = px + uDir * t * uR;
      float inside = step(cx0, q.x) * step(q.x, cx0 + 62.0) * step(cy0, q.y) * step(q.y, cy0 + 100.0);
      acc += texture2D(uTex, q / uSize).rgb * w * inside;
      wsum += w;
    }
    gl_FragColor = vec4(acc / wsum, 1.);
  }`;

// Cathodes eteintes : les 10 chiffres empiles, cuits UNE fois (au banc c'etait
// 10 lectures de texture par pixel de chiffre, a chaque image).
const FS_GHOST = `precision highp float;
  varying vec2 v; uniform sampler2D uSheet;` + GLSL_CELL + `
  void main(){
    float gh = 0.;
    for (int k = 0; k < 10; k++){ gh = max(gh, dot(cell(uSheet, float(k), v), vec3(.3,.5,.2))); }
    gl_FragColor = vec4(vec3(gh), 1.);
  }`;

const FS = `precision highp float;
  varying vec2 v;
  uniform sampler2D uSheet, uHalo, uGhostT;
  uniform vec2  uRes;
  uniform float uTime;
  uniform float uN, uNS;
  uniform float uCur[6], uPrev[6], uMix[6];
  uniform float uTX[6];
  uniform float uSX[2];
  uniform float uTW, uTop, uBot, uBaseB, uBX0, uBX1;
  uniform float uGlow, uGlowR, uCore, uFlick, uGhost, uUnder, uUnderH, uGlass, uSep;
  uniform vec3  uCyan;
  ` + GLSL_CELL + `
  float hash(float n){ return fract(sin(n) * 43758.5453); }
  float noise(float x){ float i = floor(x), f = fract(x); f = f*f*(3.-2.*f); return mix(hash(i), hash(i+1.), f); }

  vec3 gas(vec3 s){
    float L = max(s.r, max(s.g * 1.25, s.b));
    vec3 c = s * vec3(1.05, 0.62, 0.30) * 1.25;
    return mix(c, vec3(1.0, 0.86, 0.62) * L * 1.3, smoothstep(0.45, 1.0, L) * uCore);
  }

  void main(){
    vec2 px = vec2(v.x, 1.0 - v.y) * uRes;
    vec3 col = vec3(0.);
    float hw = uTW * 0.5;
    float H = uBot - uTop;

    for (int i = 0; i < 6; i++){
      if (float(i) >= uN) break;
      float lx = (px.x - uTX[i]) / hw;
      if (abs(lx) > 3.5) continue;
      float fl = 1.0 - uFlick * (0.6 * noise(uTime * 9.0 + float(i) * 17.3) + 0.4 * noise(uTime * 31.0 + float(i) * 5.1));

      float yDome = uTop + hw;
      float dx = abs(px.x - uTX[i]);
      float d;
      if (px.y < yDome) d = length(vec2(dx, px.y - yDome)) - hw;
      else d = max(dx - hw, px.y - uBot);
      float tip = max(abs(px.x - uTX[i]) - uTW * 0.08, abs(px.y - (uTop - uTW * 0.05)) - uTW * 0.09);
      float inTube = 1.0 - smoothstep(-0.6, 0.6, d);
      float inTip  = 1.0 - smoothstep(-0.5, 0.5, tip);

      float dw = uTW * 0.84, dh = dw / 0.62;
      float dcy = uTop + H * 0.56;
      vec2 duv = vec2((px.x - (uTX[i] - dw * 0.5)) / dw, (px.y - (dcy - dh * 0.5)) / dh);
      float inDigit = step(0., duv.x) * step(duv.x, 1.) * step(0., duv.y) * step(duv.y, 1.);
      float m = uMix[i];
      if (inDigit > 0.5){
        vec3 lit = mix(cell(uSheet, uPrev[i], duv), cell(uSheet, uCur[i], duv), m);
        col += vec3(0.55, 0.52, 0.5) * texture2D(uGhostT, duv).r * uGhost;
        col += gas(lit) * fl;
      }
      vec2 huv = clamp(duv, 0., 1.);
      vec3 halo = mix(cell(uHalo, uPrev[i], huv), cell(uHalo, uCur[i], huv), m);
      float hfall = inDigit > 0.5 ? 1.0 : exp(-length(max(abs(duv - 0.5) - 0.5, 0.) * vec2(dw, dh)) / max(uGlowR, 1.));
      col += gas(halo) * uGlow * hfall * fl * 1.4;

      float ax = clamp(abs(lx), 0., 1.);
      float rim = exp(-abs(d) / 0.9);
      float fres = pow(ax, 6.0) * inTube;
      float hy = clamp((uBot - px.y) / H, 0., 1.);
      float under = uUnder * exp(-hy / max(uUnderH, 0.05) * 1.6);
      col += uCyan * under * (0.10 * inTube + 0.55 * fres + 0.45 * rim);
      col += uCyan * uUnder * 0.9 * inTip * exp(-(uTop - px.y + uTW * 0.2) / 6.0) * 0.2;
      col += vec3(0.85, 0.95, 1.0) * uGlass * (0.35 * rim + 0.5 * fres
             + 0.55 * exp(-pow((lx + 0.62) / 0.07, 2.)) * inTube * smoothstep(uTop, uTop + H * 0.3, px.y)
             + 0.6 * inTip) * (0.35 + 0.65 * (1.0 - hy));
      col += uCyan * uUnder * 0.9 * exp(-pow(lx / 1.1, 2.)) * exp(-abs(px.y - uBot) / 3.0);
    }

    for (int j = 0; j < 2; j++){
      if (float(j) >= uNS) break;
      float sx = px.x - uSX[j];
      if (abs(sx) > 30.) continue;
      float sw = uTW * 0.2, top = uTop + H * 0.26;
      float bar = max(abs(sx) - sw, max(top - px.y, px.y - uBot));
      col = mix(col, vec3(0.02, 0.03, 0.04), (1.0 - smoothstep(-0.5, 0.5, bar)) * 0.9);
      for (int k = 0; k < 2; k++){
        float ly = uTop + H * 0.56 + (k == 0 ? -1.0 : 1.0) * uTW * 0.32;
        float r = length(vec2(sx, px.y - ly));
        float led = 1.0 - smoothstep(uTW * 0.12, uTW * 0.12 + 0.8, r);
        col += (mix(uCyan, vec3(1.), 0.55) * led + uCyan * exp(-r / 5.0) * 0.55) * uSep;
      }
    }

    if (px.x > uBX0 && px.x < uBX1 && px.y > uBot - 2. && px.y < uBaseB){
      float e = exp(-abs(px.y - (uBot + 3.)) / 1.2);
      col = col * 0.25 + vec3(0.012, 0.014, 0.02) + uCyan * uUnder * 0.18 * e;
    }

    col = 1.0 - exp(-col * 1.35);
    float a = clamp(max(col.r, max(col.g, col.b)), 0., 1.);
    gl_FragColor = vec4(col, a);   // premultiplie : lumiere posee sur le fond de la card
  }`;

/* Layout en px logiques : T T S T T S T T (ou T T S T T sans les secondes).
   Tubes elargis puis chiffres agrandis au banc (25/09) : ne pas retoucher sans Chris. */
function ncwLayout(n){
  const g = 0.08, g2 = 0.18, sw = 0.40;
  const nSep = n > 4 ? 2 : 1;
  const units = n + (n - 1 - nSep) * g + nSep * (2 * g2 + sw);
  const tw = Math.min(340 / units, 340 / 7.76);
  let x = (NCW_W - units * tw) / 2;
  const TX = [], SX = [];
  for (let i = 0; i < n; i++){
    if (i === 2 || i === 4){ x += g2 * tw; SX.push(x + sw * tw / 2); x += (sw + g2) * tw; }
    else if (i > 0) x += g * tw;
    TX.push(x + tw / 2); x += tw;
  }
  while (TX.length < 6) TX.push(-1000);
  while (SX.length < 2) SX.push(-1000);
  const top = 12, bot = top + tw * 1.85;
  return { tw, TX, SX, nSep, top, bot, baseB: bot + 11,
           bx0: TX[0] - tw * 0.9, bx1: TX[n - 1] + tw * 0.9 };
}

class NixieClockCardWebgl extends HTMLElement {

  constructor(){
    super();
    this.attachShadow({ mode: 'open' });
    this._built = false;
    this._gen = 0;
    this._frameB = this._frame.bind(this);
  }

  static getStubConfig(){ return { use_military: true, hide_seconds: false }; }
  getCardSize(){ return 2; }

  setConfig(config){
    if (!config) throw new Error('nixie-clock-card-webgl : config manquante');
    this._config = config;
    const P = {};
    for (const k in NCW_DEF){
      const v = Number(config[k]);
      P[k] = (config[k] != null && Number.isFinite(v)) ? v : NCW_DEF[k];
    }
    P.glow_r = Math.max(0.5, Math.min(30, P.glow_r));
    P.fade = Math.max(0, P.fade);
    this._P = P;
    this._military = config.use_military != null ? !!config.use_military : true;
    this._nT = config.hide_seconds ? 4 : 6;
    this._underCss = config.under_color || 'var(--accent-color, #00fff9)';
    if (this._built) this._teardown();
    if (this.isConnected) this._build();
  }

  set hass(h){
    this._hass = h;
    if (!this._config) return;
    if (!this._built){ if (this.isConnected) this._build(); return; }
    // changement de theme : on relit la couleur des LED
    if (h && h.themes !== this._themesRef){ this._themesRef = h.themes; this._resolveColors(); this._dirty = true; }
  }

  connectedCallback(){
    if (!this._config) return;
    if (!this._built) this._build(); else this._resume();
  }

  disconnectedCallback(){ this._pause(); }

  /* ───────────── construction ───────────── */
  _build(){
    const sr = this.shadowRoot;
    sr.innerHTML = '';
    const st = document.createElement('style');
    st.textContent = ':host{display:block}'
      + 'ha-card{position:relative;overflow:visible;box-sizing:border-box;width:100%;padding:0}'
      + '.wrap{position:relative;width:100%;aspect-ratio:' + NCW_W + '/' + NCW_H + '}'
      + 'canvas{position:absolute;inset:0;width:100%;height:100%;display:block}'
      + '.probe{position:absolute;width:0;height:0;overflow:hidden;visibility:hidden}';
    sr.appendChild(st);
    const card = document.createElement('ha-card');
    const wrap = document.createElement('div'); wrap.className = 'wrap';
    const cv = document.createElement('canvas');
    this._L = ncwLayout(this._nT);
    // boite des tubes, ancre du chat (equivalent du displayWrap de la card d'origine)
    const L0 = this._L, disp = document.createElement('div');
    disp.style.cssText = 'position:absolute;pointer-events:none;'
      + 'left:' + ((L0.TX[0] - L0.tw / 2) / NCW_W * 100) + '%;'
      + 'right:' + ((NCW_W - L0.TX[this._nT - 1] - L0.tw / 2) / NCW_W * 100) + '%;'
      + 'top:' + ((L0.top - L0.tw * 0.14) / NCW_H * 100) + '%;'
      + 'bottom:' + ((NCW_H - L0.baseB) / NCW_H * 100) + '%;';
    wrap.appendChild(cv); wrap.appendChild(disp); card.appendChild(wrap); sr.appendChild(card);
    this._card = card; this._wrap = wrap; this._canvas = cv; this._disp = disp;

    this._digits = { cur:[0,0,0,0,0,0], prev:[0,0,0,0,0,0], t0:[-1e9,-1e9,-1e9,-1e9,-1e9,-1e9] };
    this._first = true;
    this._lastSec = -1;
    this._tChange = -1e9;
    this._t0 = performance.now();

    this._onLost = e => {
      if (e.target !== this._canvas) return;       // echo d'un canvas mort
      e.preventDefault();
      this._ready = false; this._glLost = true;
    };
    this._onRestored = e => {
      if (e.target !== this._canvas) return;
      this._glLost = false;
      this._glInit();
    };
    cv.addEventListener('webglcontextlost', this._onLost);
    cv.addEventListener('webglcontextrestored', this._onRestored);

    this._built = true;
    this._resolveColors();
    this._glInit();
    this._resume();
  }

  _teardown(){
    this._pause();
    if (this._canvas){
      this._canvas.removeEventListener('webglcontextlost', this._onLost);
      this._canvas.removeEventListener('webglcontextrestored', this._onRestored);
    }
    this._gen++;
    this._gl = null; this._ready = false;
    this.shadowRoot.innerHTML = '';
    this._built = false;
  }

  _resolveColors(){
    let c = [0, 1, 249 / 255];
    try {
      const probe = document.createElement('span');
      probe.className = 'probe';
      probe.style.color = this._underCss;
      this.shadowRoot.appendChild(probe);
      const m = getComputedStyle(probe).color.match(/(\d+(?:\.\d+)?),\s*(\d+(?:\.\d+)?),\s*(\d+(?:\.\d+)?)/);
      probe.remove();
      if (m) c = [m[1] / 255, m[2] / 255, m[3] / 255];
    } catch (e) { /* on garde le cyan par defaut */ }
    this._cyan = c;
  }

  /* ───────────── WebGL ───────────── */
  _glInit(){
    const gen = ++this._gen;
    const cv = this._canvas;
    this._ready = false;
    const gl = cv.getContext('webgl', { premultipliedAlpha: true, alpha: true, antialias: false });
    if (!gl){ console.warn('[nixie-clock-card-webgl] WebGL indisponible'); return; }
    this._gl = gl;
    const sh = (type, src) => {
      const s = gl.createShader(type); gl.shaderSource(s, src); gl.compileShader(s);
      if (!gl.getShaderParameter(s, gl.COMPILE_STATUS) && !gl.isContextLost()) throw new Error(gl.getShaderInfoLog(s));
      return s;
    };
    const prog = fs => {
      const p = gl.createProgram();
      gl.attachShader(p, sh(gl.VERTEX_SHADER, VS)); gl.attachShader(p, sh(gl.FRAGMENT_SHADER, fs));
      gl.bindAttribLocation(p, 0, 'p'); gl.linkProgram(p);
      if (!gl.getProgramParameter(p, gl.LINK_STATUS) && !gl.isContextLost()) throw new Error(gl.getProgramInfoLog(p));
      const U = {}; const n = gl.getProgramParameter(p, gl.ACTIVE_UNIFORMS) || 0;
      for (let i = 0; i < n; i++){ const nm = gl.getActiveUniform(p, i).name.replace('[0]', ''); U[nm] = gl.getUniformLocation(p, nm); }
      return { p, U };
    };
    let PB, PG, PS;
    try { PB = prog(FS_BLUR); PG = prog(FS_GHOST); PS = prog(FS); }
    catch (e){ console.error('[nixie-clock-card-webgl] shader :', e.message || e); return; }
    const buf = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1, 1,-1, -1,1, 1,1]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

    // Textures NPOT : CLAMP + LINEAR, jamais de mipmap (texture noire muette en WebGL 1).
    const tex = (w, h, img) => {
      const t = gl.createTexture(); gl.bindTexture(gl.TEXTURE_2D, t);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
      if (img) gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, gl.RGB, gl.UNSIGNED_BYTE, img);
      else gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, w, h, 0, gl.RGB, gl.UNSIGNED_BYTE, null);
      return t;
    };
    const fbo = t => {
      const f = gl.createFramebuffer(); gl.bindFramebuffer(gl.FRAMEBUFFER, f);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, t, 0);
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      return f;
    };
    const R = { gl, PB, PG, PS, sheet: null, halo: [], hf: [], ghost: null, gf: null, haloR: -1 };
    this._R = R;
    const img = new Image();
    img.onload = () => {
      if (gen !== this._gen || this._gl !== gl || gl.isContextLost()) return;   // build perime
      R.sheet = tex(744, 200, img);
      R.halo = [tex(744, 200, null), tex(744, 200, null)];
      R.hf = [fbo(R.halo[0]), fbo(R.halo[1])];
      R.ghost = tex(62, 100, null); R.gf = fbo(R.ghost);
      // cuisson des cathodes eteintes, une fois
      gl.useProgram(PG.p); gl.viewport(0, 0, 62, 100);
      gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D, R.sheet); gl.uniform1i(PG.U.uSheet, 0);
      gl.bindFramebuffer(gl.FRAMEBUFFER, R.gf); gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      this._reblur();
      this._ready = true; this._dirty = true;
      if (this._reducedTick) this._reducedTick();
    };
    img.src = 'data:image/png;base64,' + NCW_SHEET;
  }

  _reblur(){
    const R = this._R, gl = R.gl, P = this._P, PB = R.PB;
    const r = P.glow_r / (this._L.tw * 0.84 / 62);   // rayon px logiques -> px de planche
    gl.useProgram(PB.p); gl.viewport(0, 0, 744, 200);
    gl.uniform2f(PB.U.uSize, 744, 200); gl.uniform1f(PB.U.uR, r); gl.uniform1i(PB.U.uTex, 0);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindFramebuffer(gl.FRAMEBUFFER, R.hf[0]); gl.bindTexture(gl.TEXTURE_2D, R.sheet);
    gl.uniform2f(PB.U.uDir, 1, 0); gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    gl.bindFramebuffer(gl.FRAMEBUFFER, R.hf[1]); gl.bindTexture(gl.TEXTURE_2D, R.halo[0]);
    gl.uniform2f(PB.U.uDir, 0, 1); gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    R.haloR = P.glow_r;
  }

  _fitCanvas(){
    const cv = this._canvas;
    const cw = this._wrap ? this._wrap.clientWidth : 0;
    if (!cw) return false;
    const dpr = NCW_IS_LOW_POWER ? 1 : Math.min(window.devicePixelRatio || 1, 2);
    const w = Math.round(cw * dpr), h = Math.round(cw * NCW_H / NCW_W * dpr);
    if (cv.width !== w || cv.height !== h){ cv.width = w; cv.height = h; this._dirty = true; }
    return true;
  }

  _updateDigits(now){
    // getHours() direct : toLocaleTimeString(hour12:false) sort « 24 » a minuit sous Chrome
    const dt = new Date(), p2 = n => String(n).padStart(2, '0');
    let h = dt.getHours();
    if (!this._military) h = (h % 12) || 12;
    const s = p2(h) + p2(dt.getMinutes()) + p2(dt.getSeconds());
    const D = this._digits;
    for (let i = 0; i < this._nT; i++){
      const d = +s.charAt(i) || 0;
      if (this._first){ D.cur[i] = D.prev[i] = d; continue; }
      if (d !== D.cur[i]){ D.prev[i] = D.cur[i]; D.cur[i] = d; D.t0[i] = now; this._tChange = now; this._dirty = true; }
    }
    if (this._first){ this._first = false; this._dirty = true; }
  }

  _draw(now){
    const R = this._R;
    if (!this._ready || this._glLost || !R || this._gl !== R.gl) return;
    const gl = R.gl, P = this._P, L = this._L, D = this._digits, U = R.PS.U;
    if (!this._fitCanvas()) return;
    if (R.haloR !== P.glow_r) this._reblur();
    const mixv = [];
    for (let i = 0; i < 6; i++) mixv.push(P.fade <= 0 ? 1 : Math.min(1, (now - D.t0[i]) / P.fade));
    gl.useProgram(R.PS.p); gl.viewport(0, 0, this._canvas.width, this._canvas.height);
    gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT);
    gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D, R.sheet); gl.uniform1i(U.uSheet, 0);
    gl.activeTexture(gl.TEXTURE1); gl.bindTexture(gl.TEXTURE_2D, R.halo[1]); gl.uniform1i(U.uHalo, 1);
    gl.activeTexture(gl.TEXTURE2); gl.bindTexture(gl.TEXTURE_2D, R.ghost); gl.uniform1i(U.uGhostT, 2);
    gl.uniform2f(U.uRes, NCW_W, NCW_H);
    gl.uniform1f(U.uTime, ((now - this._t0) / 1000) % 1000);
    gl.uniform1f(U.uN, this._nT); gl.uniform1f(U.uNS, L.nSep);
    gl.uniform1fv(U.uCur, D.cur); gl.uniform1fv(U.uPrev, D.prev); gl.uniform1fv(U.uMix, mixv);
    gl.uniform1fv(U.uTX, L.TX); gl.uniform1fv(U.uSX, L.SX);
    gl.uniform1f(U.uTW, L.tw); gl.uniform1f(U.uTop, L.top); gl.uniform1f(U.uBot, L.bot);
    gl.uniform1f(U.uBaseB, L.baseB); gl.uniform1f(U.uBX0, L.bx0); gl.uniform1f(U.uBX1, L.bx1);
    gl.uniform1f(U.uGlow, P.glow); gl.uniform1f(U.uGlowR, P.glow_r); gl.uniform1f(U.uCore, P.core);
    gl.uniform1f(U.uFlick, this._reduced ? 0 : P.flicker); gl.uniform1f(U.uGhost, P.ghost);
    gl.uniform1f(U.uUnder, P.under); gl.uniform1f(U.uUnderH, P.under_h);
    gl.uniform1f(U.uGlass, P.glass); gl.uniform1f(U.uSep, P.sep);
    gl.uniform3fv(U.uCyan, this._cyan);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    this._lastDraw = now; this._dirty = false;
  }

  /* ───────────── boucle : pleine cadence seulement pendant le fondu ───────────── */
  _frame(now){
    if (!this._running) return;
    this._raf = requestAnimationFrame(this._frameB);
    const sec = Math.floor(Date.now() / 1000);
    if (sec !== this._lastSec){ this._lastSec = sec; this._updateDigits(now); }
    const fading = now - this._tChange < this._P.fade + 20;
    let minMs;
    if (fading) minMs = NCW_IS_LOW_POWER ? 1000 / 24 : 0;
    else if (this._P.flicker > 0) minMs = NCW_IS_LOW_POWER ? 1000 / 8 : 1000 / 12;   // palier de repos
    else minMs = Infinity;                                                            // image fixe
    if (!this._dirty && now - (this._lastDraw || 0) < minMs - 2) return;
    this._draw(now);
  }

  _startLoop(){
    if (this._running || this._locks > 0) return;
    this._running = true;
    this._dirty = true;
    this._raf = requestAnimationFrame(this._frameB);
  }
  _stopLoop(){
    this._running = false;
    if (this._raf){ cancelAnimationFrame(this._raf); this._raf = 0; }
  }

  // Compteur de verrous (onglet cache, hors ecran) : recopie de thermal-core-card.
  _lock(on){
    this._locks = Math.max(0, (this._locks || 0) + (on ? 1 : -1));
    if (this._reduced) return;
    if (this._locks > 0) this._stopLoop(); else this._startLoop();
  }

  _watch(){
    this._locks = 0; this._vuDoc = !document.hidden; this._vuEcran = true;
    if (!this._vuDoc) this._locks++;
    this._onVis = () => { const v = !document.hidden; if (v !== this._vuDoc){ this._vuDoc = v; this._lock(!v); } };
    this._onHide = () => { if (this._vuDoc){ this._vuDoc = false; this._lock(true); } };
    this._onShow = () => { if (!this._vuDoc){ this._vuDoc = true; this._lock(false); } };
    document.addEventListener('visibilitychange', this._onVis);
    window.addEventListener('pagehide', this._onHide);
    window.addEventListener('pageshow', this._onShow);
    if (typeof IntersectionObserver === 'function'){
      this._io = new IntersectionObserver(ents => {
        const v = ents[ents.length - 1].isIntersecting;
        if (v !== this._vuEcran){ this._vuEcran = v; this._lock(!v); }
      }, { threshold: 0 });
      this._io.observe(this._canvas);
    }
  }

  _unwatch(){
    if (this._onVis) document.removeEventListener('visibilitychange', this._onVis);
    if (this._onHide) window.removeEventListener('pagehide', this._onHide);
    if (this._onShow) window.removeEventListener('pageshow', this._onShow);
    this._onVis = this._onHide = this._onShow = null;
    if (this._io){ this._io.disconnect(); this._io = null; }
  }

  _resume(){
    if (!this._built) return;
    // contexte perdu pendant l'absence, ou canvas remplace : on reconstruit
    // (pas de _gl du tout = WebGL indisponible : ne pas reconstruire en boucle)
    if (this._gl && !this._glLost && (this._gl.canvas !== this._canvas || this._gl.isContextLost())){
      this._teardown(); this._build(); return;
    }
    this._pause();
    this._ro = new ResizeObserver(() => { this._fitCanvas(); if (this._reduced) this._draw(performance.now()); });
    this._ro.observe(this._wrap);
    this._reduced = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
    this._watch();
    if (this._reduced){
      // pas d'animation : une image par seconde, sans fondu ni scintillement
      this._reducedTick = () => {
        if (document.hidden) return;
        this._updateDigits(-1e9); this._draw(performance.now());
      };
      this._reducedTick();
      this._reducedIv = setInterval(this._reducedTick, 1000);
    } else if (this._locks === 0){
      this._startLoop();
    }
    this._initGhost(this._disp);
  }

  _pause(){
    this._stopLoop();
    this._unwatch();
    if (this._ro){ this._ro.disconnect(); this._ro = null; }
    if (this._reducedIv){ clearInterval(this._reducedIv); this._reducedIv = null; }
    this._reducedTick = null;
    this._stopGhost();
  }

  /* ── GLITCH le chat : recopie de nixie-clock-card ── */
  _initGhost(anchor){
    this._stopGhost();
    if (!anchor) return;
    if (window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const cfg = this._config || {};
    if (cfg.glitch === false) return;
    const size  = cfg.glitch_size  || 64;
    const right = cfg.glitch_right != null ? cfg.glitch_right : -26;
    const top   = cfg.glitch_top   != null ? cfg.glitch_top   : -40;
    const color = cfg.glitch_color || this._underCss;
    const g = document.createElement('div');
    g.style.cssText = 'position:absolute;pointer-events:none;z-index:6;opacity:0;'
      + 'width:' + size + 'px;height:' + size + 'px;'
      + 'right:' + right + 'px;top:' + top + 'px;color:' + color + ';';
    g.innerHTML = '<svg viewBox="15 28 666 666" style="width:100%;height:100%;'
      + 'filter:drop-shadow(0 0 5px currentColor) drop-shadow(0 0 12px currentColor);">'
      + '<g transform="matrix(1.25 0 0 -1.25 0 1000)"><g transform="matrix(.8765 0 0 .8765 327.75 398.73)">'
      + '<path fill="currentColor" d="' + NCW_GLITCH_PATH + '"/></g></g></svg>';
    anchor.appendChild(g);
    this._ghostEl = g;
    this._ghostTimers = new Set();
    const t = setTimeout(() => this._spawnGhost(), 4000 + Math.random() * 8000);
    this._ghostTimers.add(t);
  }

  _spawnGhost(){
    const g = this._ghostEl;
    if (!g || !g.isConnected) return;
    const cfg = this._config || {};
    const dur = cfg.glitch_dur || 2400;
    const opMax = cfg.glitch_opacity || 0.8;
    const t0 = performance.now();
    const step = now => {
      if (!g.isConnected) return;
      const p = (now - t0) / dur;
      if (p >= 1){
        g.style.opacity = 0;
        const gap = (cfg.glitch_gap || 25) * 1000 * (0.6 + Math.random() * 0.9);
        const t = setTimeout(() => this._spawnGhost(), gap);
        if (this._ghostTimers) this._ghostTimers.add(t);
        return;
      }
      let env;
      if (p < 0.25) env = p / 0.25;
      else if (p < 0.70) env = 1;
      else env = 1 - (p - 0.70) / 0.30;
      const stable = (p > 0.30 && p < 0.65);
      const flick = stable ? 1 : (Math.random() < 0.5 ? 0.55 : 1);
      const float = Math.sin(p * Math.PI * 6) * 1.2 * (1 - env * 0.4);
      g.style.opacity = opMax * env * flick;
      g.style.transform = 'translateY(' + float + 'px)';
      this._ghostRaf = requestAnimationFrame(step);
    };
    this._ghostRaf = requestAnimationFrame(step);
  }

  _stopGhost(){
    if (this._ghostTimers) this._ghostTimers.forEach(clearTimeout);
    this._ghostTimers = null;
    if (this._ghostRaf){ cancelAnimationFrame(this._ghostRaf); this._ghostRaf = null; }
    if (this._ghostEl){ this._ghostEl.remove(); this._ghostEl = null; }
  }
}

if (!customElements.get(NCW_TAG)) {
  customElements.define(NCW_TAG, NixieClockCardWebgl);
}
window.customCards = window.customCards || [];
if (!window.customCards.some(c => c.type === NCW_TAG || c.type === 'custom:' + NCW_TAG)) {
  window.customCards.push({ type: NCW_TAG, name: 'Nixie Clock (WebGL)',
    description: 'Horloge nixie en WebGL : tubes IN-14, retroeclairage cyan du theme.' });
}

console.info(
  '%c 🕐 nixie-clock-card-webgl v' + NCW_VERSION + ' %c Neo Tokyo ',
  'background:#FF6A00;color:#000;padding:2px 4px;border-radius:3px 0 0 3px;font-weight:bold;',
  'background:#040811;color:#00fff9;padding:2px 4px;border-radius:0 3px 3px 0;'
);
})();
